/**
 * @distilled.cloud/opensearch -- OpenSearch SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenSearch OpenAPI spec,
 * mirrored at `specs/spec-mirror-opensearch/specs/`. Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as OpenSearch from "@distilled.cloud/opensearch";
 *
 * const program = Effect.gen(function* () {
 *   yield* OpenSearch.index({ index: "logs", refresh: "true", document: { message: "hello" } });
 *   const result = yield* OpenSearch.searchByIndex({
 *     index: "logs",
 *     query: { match: { message: "hello" } },
 *   });
 *   return result.hits.hits;
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   OpenSearch.CredentialsFromEnv,
 *   OpenSearch.OpenSearchProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  OpenSearchProtocol,
  type OpenSearchOpError,
  type OpenSearchOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts -- the ops actually raise the
// service-local classes.
export * from "./services/opensearch.ts";
export { BadRequest, Conflict, Forbidden, NotFound } from "./services/opensearch.ts";
